/* eslint-disable space-in-parens */

import AccessorArray = require( '@stdlib/array/base/accessor' );
import gcompanion = require( './index' );


// TESTS //

// The function returns a collection...
{
	const x = new Float64Array( 4 );
	const out = new Float64Array( 9 );

	gcompanion( 'row-major', 4, x, 1, out, 3 ); // $ExpectType Float64Array
	gcompanion( 'row-major', 4, x, 1, new AccessorArray( out ), 3 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not a valid order...
{
	const x = new Float64Array( 4 );
	const out = new Float64Array( 9 );

	gcompanion( 10, 4, x, 1, out, 3 ); // $ExpectError
	gcompanion( true, 4, x, 1, out, 3 ); // $ExpectError
	gcompanion( false, 4, x, 1, out, 3 ); // $ExpectError
	gcompanion( null, 4, x, 1, out, 3 ); // $ExpectError
	gcompanion( undefined, 4, x, 1, out, 3 ); // $ExpectError
	gcompanion( [], 4, x, 1, out, 3 ); // $ExpectError
	gcompanion( {}, 4, x, 1, out, 3 ); // $ExpectError
	gcompanion( ( x: number ): number => x, 4, x, 1, out, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const x = new Float64Array( 4 );
	const out = new Float64Array( 9 );

	gcompanion( 'row-major', '10', x, 1, out, 3 ); // $ExpectError
	gcompanion( 'row-major', true, x, 1, out, 3 ); // $ExpectError
	gcompanion( 'row-major', false, x, 1, out, 3 ); // $ExpectError
	gcompanion( 'row-major', null, x, 1, out, 3 ); // $ExpectError
	gcompanion( 'row-major', undefined, x, 1, out, 3 ); // $ExpectError
	gcompanion( 'row-major', [], x, 1, out, 3 ); // $ExpectError
	gcompanion( 'row-major', {}, x, 1, out, 3 ); // $ExpectError
	gcompanion( 'row-major', ( x: number ): number => x, x, 1, out, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a collection...
{
	const out = new Float64Array( 9 );

	gcompanion( 'row-major', 4, 10, 1, out, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, true, 1, out, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, false, 1, out, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, null, 1, out, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, undefined, 1, out, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, {}, 1, out, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, ( x: number ): number => x, 1, out, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a number...
{
	const x = new Float64Array( 4 );
	const out = new Float64Array( 9 );

	gcompanion( 'row-major', 4, x, '10', out, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, x, true, out, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, x, false, out, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, x, null, out, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, x, undefined, out, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, x, [], out, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, x, {}, out, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, x, ( x: number ): number => x, out, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not a collection...
{
	const x = new Float64Array( 4 );

	gcompanion( 'row-major', 4, x, 1, 10, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, true, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, false, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, null, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, undefined, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, {}, 3 ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, ( x: number ): number => x, 3 ); // $ExpectError
}

// The compiler throws an error if the function is provided a sixth argument which is not a number...
{
	const x = new Float64Array( 4 );
	const out = new Float64Array( 9 );

	gcompanion( 'row-major', 4, x, 1, out, '10' ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, out, true ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, out, false ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, out, null ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, out, undefined ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, out, [] ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, out, {} ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, out, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Float64Array( 4 );
	const out = new Float64Array( 9 );

	gcompanion(); // $ExpectError
	gcompanion( 'row-major' ); // $ExpectError
	gcompanion( 'row-major', 4 ); // $ExpectError
	gcompanion( 'row-major', 4, x ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1 ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, out ); // $ExpectError
	gcompanion( 'row-major', 4, x, 1, out, 3, 10 ); // $ExpectError
}

// Attached to the main export is an `ndarray` method which returns a collection...
{
	const x = new Float64Array( 4 );
	const out = new Float64Array( 9 );

	gcompanion.ndarray( 4, x, 1, 0, out, 3, 1, 0 ); // $ExpectType Float64Array
	gcompanion.ndarray( 4, x, 1, 0, new AccessorArray( out ), 3, 1, 0 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const x = new Float64Array( 4 );
	const out = new Float64Array( 9 );

	gcompanion.ndarray( '10', x, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcompanion.ndarray( true, x, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcompanion.ndarray( false, x, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcompanion.ndarray( null, x, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcompanion.ndarray( undefined, x, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcompanion.ndarray( [], x, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcompanion.ndarray( {}, x, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcompanion.ndarray( ( x: number ): number => x, x, 1, 0, out, 3, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a collection...
{
	const out = new Float64Array( 9 );

	gcompanion.ndarray( 4, 10, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcompanion.ndarray( 4, true, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcompanion.ndarray( 4, false, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcompanion.ndarray( 4, null, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcompanion.ndarray( 4, undefined, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcompanion.ndarray( 4, {}, 1, 0, out, 3, 1, 0 ); // $ExpectError
	gcompanion.ndarray( 4, ( x: number ): number => x, 1, 0, out, 3, 1, 0 ); // $ExpectError
}

