// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const x = new Float64Array( 4 );
	const out = new Float64Array( 9 );

	gcompanion.ndarray(); // $ExpectError
	gcompanion.ndarray( 4 ); // $ExpectError
	gcompanion.ndarray( 4, x ); // $ExpectError
	gcompanion.ndarray( 4, x, 1 ); // $ExpectError
	gcompanion.ndarray( 4, x, 1, 0 ); // $ExpectError
	gcompanion.ndarray( 4, x, 1, 0, out ); // $ExpectError
	gcompanion.ndarray( 4, x, 1, 0, out, 3 ); // $ExpectError
	gcompanion.ndarray( 4, x, 1, 0, out, 3, 1 ); // $ExpectError
	gcompanion.ndarray( 4, x, 1, 0, out, 3, 1, 0, 10 ); // $ExpectError
}
